target.css:
:root {
  --ink: #30251f;
  --paper: #fffaf0;
  --leather: #a55b35;
  --clay: #eac7a6;
  --cream: #f7e7d1;
  --line: #d8b995;
  --moss: #53694e;
  --white: #ffffff;
}

.edge-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  color: var(--white);
  background: var(--ink);
}

.bench-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.status {
  padding: 4px 8px;
  color: var(--ink);
  background: var(--cream);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.edge-main {
  display: grid;
  grid-template-columns: 126px 1fr;
  gap: 16px;
  padding: 14px 16px 12px;
}

.swatch {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 92px;
  margin: 0;
  padding: 12px;
  background: var(--clay);
  border: 1px solid var(--leather);
  border-radius: 12px 12px 3px 12px;
}

.swatch-mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  color: var(--white);
  background: var(--leather);
  border-radius: 50%;
  font-size: 16px;
}

.swatch figcaption {
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
}

.recipe h1 {
  margin: 2px 0 2px;
  font-size: 21px;
  line-height: 1.1;
}

.recipe p {
  margin: 0 0 12px;
  color: var(--moss);
  font-size: 13px;
  font-weight: 600;
}

.steps {
  display: flex;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.steps li {
  padding: 5px 8px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  background: var(--cream);
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  font-size: 12px;
  line-height: 1.3;
}

.card-footer strong {
  color: var(--leather);
}

.complete-button {
  padding: 8px 11px;
  color: var(--white);
  background: var(--moss);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

